using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;using Tesis.Api.Core;using Tesis.Domain.Entities;using Tesis.Domain.Enums;using Tesis.Infrastructure.Persistence;using TesisEntidad = Tesis.Domain.Entities.Tesis;public partial class Program{    private const string CorreoDemoAlumno = "alumno.demo@upt.edu.mx";    private const string CorreoDemoAsesor = "asesor@upt.edu.mx";    private const string CorreoDemoCoAsesor = "coasesor@upt.edu.mx";    private const string CorreoDemoDirector = "director@upt.edu.mx";    private const string CorreoDemoAdministrador = "admin@upt.edu.mx";    private const string ContrasenaDemo = "Demo1234!";    private const string ProgramaMaestriaTi = "Maestría en Tecnologías de la Información";    private static async Task SembrarDatosDesarrolloAsync(        TesisDbContext contexto,        UserManager<Usuario> userManager)    {        await CrearUsuarioYRoleAsync(userManager, CorreoDemoAlumno, ConstantesRol.Alumno);        var idAsesor = await CrearUsuarioYRoleAsync(userManager, CorreoDemoAsesor, ConstantesRol.Docente);        var idCoAsesor = await CrearUsuarioYRoleAsync(userManager, CorreoDemoCoAsesor, ConstantesRol.Docente);        var idDirector = await CrearUsuarioYRoleAsync(userManager, CorreoDemoDirector, ConstantesRol.DirectorDePosgrado);        await CrearUsuarioYRoleAsync(userManager, CorreoDemoAdministrador, ConstantesRol.Administrador);        var alumnoDemo = await contexto.Alumnos            .Include(a => a.Usuario)            .FirstOrDefaultAsync(a => a.Usuario != null && a.Usuario.Email == CorreoDemoAlumno);        if (alumnoDemo is null)        {            var usuarioAlumno = await userManager.FindByEmailAsync(CorreoDemoAlumno);            contexto.Alumnos.Add(new Alumno            {                IdUsuario = usuarioAlumno!.Id,                Nombre = "José Ramírez",                NumeroControl = "UPT20231001",                Correo = CorreoDemoAlumno,            });        }        var asesorDemo = await contexto.Profesores            .Include(p => p.Usuario)            .FirstOrDefaultAsync(p => p.Usuario != null && p.Usuario.Id == idAsesor);        if (asesorDemo is null)        {            asesorDemo = new Profesor { IdUsuario = idAsesor, Nombre = "Dra. Ana Beltrán", Activo = true };            contexto.Profesores.Add(asesorDemo);            await contexto.SaveChangesAsync();        }        var coAsesorDemo = await contexto.Profesores            .Include(p => p.Usuario)            .FirstOrDefaultAsync(p => p.Usuario != null && p.Usuario.Id == idCoAsesor);        if (coAsesorDemo is null)        {            coAsesorDemo = new Profesor { IdUsuario = idCoAsesor, Nombre = "Dr. Luis Cortés", Activo = true };            contexto.Profesores.Add(coAsesorDemo);            await contexto.SaveChangesAsync();        }        await AsegurarProgramaProfesorAsync(contexto, asesorDemo.IdProfesor, NivelPosgrado.Maestria, ProgramaMaestriaTi);        await AsegurarProgramaProfesorAsync(contexto, coAsesorDemo.IdProfesor, NivelPosgrado.Maestria, ProgramaMaestriaTi);        await AsegurarProgramaProfesorAsync(contexto, coAsesorDemo.IdProfesor, NivelPosgrado.Doctorado, "Doctorado en Ciencias de la Ingeniería");        await contexto.SaveChangesAsync();        var alumnoEjemplo1 = await ObtenerOSembrarAlumnoDemoAsync(contexto, "María López", "UPT20221001", "maria.lopez@upt.edu.mx", userManager);        var alumnoEjemplo2 = await ObtenerOSembrarAlumnoDemoAsync(contexto, "Carlos Vega", "UPT20221002", "carlos.vega@upt.edu.mx", userManager);        var alumnoEjemplo3 = await ObtenerOSembrarAlumnoDemoAsync(contexto, "Ana Guzmán", "UPT20211003", "ana.guzman@upt.edu.mx", userManager);        await SembrarTesisAceptadaAsync(            contexto,            alumnoEjemplo1.IdAlumno,            "Sistemas de monitoreo con aprendizaje federado en redes de campus",            NivelPosgrado.Maestria,            ProgramaMaestriaTi,            asesorDemo.IdProfesor,            idDirector,            new[] { (Nombre: "Artículo de revista", Descripcion: "Publicación académica arbitrada.") });        await SembrarTesisAceptadaAsync(            contexto,            alumnoEjemplo2.IdAlumno,            "Optimización energética en edificios inteligentes mediante redes neuronales",            NivelPosgrado.Maestria,            ProgramaMaestriaTi,            asesorDemo.IdProfesor,            idDirector,            new[] { (Nombre: "Artículo de congreso", Descripcion: "Memorias y proceedings de congresos.") });        await SembrarTesisAceptadaAsync(            contexto,            alumnoEjemplo3.IdAlumno,            "Modelado de materiales compuestos para aplicaciones aeroespaciales",            NivelPosgrado.Doctorado,            "Doctorado en Ciencias de la Ingeniería",            coAsesorDemo.IdProfesor,            idDirector,            new[] { (Nombre: "Capítulo de libro", Descripcion: "Contribución en volumen colectivo.") });        await SembrarTesisRechazadaAsync(            contexto,            alumnoEjemplo1.IdAlumno,            "Aplicaciones móviles de bajo costo para teleeducación rural",            NivelPosgrado.Maestria,            ProgramaMaestriaTi,            asesorDemo.IdProfesor,            idDirector);        await contexto.SaveChangesAsync();    }    private static async Task<SembrarAlumnoDemo> ObtenerOSembrarAlumnoDemoAsync(        TesisDbContext contexto,        string nombre,        string numeroControl,        string correo,        UserManager<Usuario> userManager)    {        var alumno = await contexto.Alumnos.FirstOrDefaultAsync(a => a.Correo == correo);        if (alumno is null)        {            var usuario = await userManager.FindByEmailAsync(correo);            if (usuario is null)            {                await CrearUsuarioYRoleAsync(userManager, correo, ConstantesRol.Alumno);                usuario = await userManager.FindByEmailAsync(correo);            }            alumno = new Alumno            {                IdUsuario = usuario!.Id,                Nombre = nombre,                NumeroControl = numeroControl,                Correo = correo,            };            contexto.Alumnos.Add(alumno);            await contexto.SaveChangesAsync();        }        return new SembrarAlumnoDemo(alumno.IdAlumno);    }    private static async Task SembrarTesisRechazadaAsync(        TesisDbContext contexto,        int idAlumno,        string titulo,        NivelPosgrado nivel,        string programa,        int idAsesor,        int idDirector)    {var tesis = new TesisEntidad(idAlumno, titulo, nivel, programa, idAsesor, false, null);        if (await contexto.Tesis.AnyAsync(t => t.Titulo == titulo && t.IdAlumno == idAlumno))        {            return;        }        contexto.Tesis.Add(tesis);        var confirmacion = new ConfirmacionAsesoria { IdProfesor = idAsesor, Tipo = TipoConfirmacion.Asesor };        confirmacion.Confirmar();        tesis.AgregarConfirmacion(confirmacion);        tesis.ConfirmarAsesoria();        tesis.SubirDocumento(new DocumentoTesis { Nombre = "tesis-final.pdf" });        tesis.RegistrarRevisionIA(ResultadoRevisionIA.Valido, 88m);        tesis.AceptarRevision(idAsesor);        tesis.EmitirDictamen(idDirector, ResultadoDictamen.Rechazada, "La coherencia metodológica no cumple el criterio.");    }    private static async Task SembrarTesisAceptadaAsync(        TesisDbContext contexto,        int idAlumno,        string titulo,        NivelPosgrado nivel,        string programa,        int idAsesor,        int idDirector,        IReadOnlyCollection<(string Nombre, string Descripcion)> tiposArticulo)    {var tesis = new TesisEntidad(idAlumno, titulo, nivel, programa, idAsesor, false, null);        if (await contexto.Tesis.AnyAsync(t => t.Titulo == titulo && t.IdAlumno == idAlumno))        {            return;        }        contexto.Tesis.Add(tesis);        var confirmacion = new ConfirmacionAsesoria { IdProfesor = idAsesor, Tipo = TipoConfirmacion.Asesor };        confirmacion.Confirmar();        tesis.AgregarConfirmacion(confirmacion);        tesis.ConfirmarAsesoria();        tesis.SubirDocumento(new DocumentoTesis { Nombre = "tesis-final.pdf" });        tesis.RegistrarRevisionIA(ResultadoRevisionIA.Valido, 94m);        tesis.AceptarRevision(idAsesor);        tesis.EmitirDictamen(idDirector, ResultadoDictamen.Aceptada, "Trabajo aprobado.");        if (tiposArticulo.Any())        {            foreach (var tipo in tiposArticulo)            {                var tipoArticulo = await contexto.TiposArticulo                    .FirstOrDefaultAsync(t => t.Nombre == tipo.Nombre);                if (tipoArticulo is null)                {                    tipoArticulo = new TipoArticulo { Nombre = tipo.Nombre, Descripcion = tipo.Descripcion };                    contexto.TiposArticulo.Add(tipoArticulo);                    await contexto.SaveChangesAsync();                }                tesis.Articulos.Add(new Articulo(                    $"Artículo sobre {titulo.Split(' ').Take(4).Aggregate((a, b) => a + " " + b).ToLowerInvariant()}",                    "https://doi.org/10.1000/demo",                    "10.1000/demo",                    tipoArticulo.IdTipoArticulo));            }        }    }    private sealed record SembrarAlumnoDemo(int IdAlumno);    private static async Task<int> CrearUsuarioYRoleAsync(        UserManager<Usuario> userManager,        string correo,        string rol)    {        var usuario = await userManager.FindByEmailAsync(correo);        if (usuario is null)        {            usuario = new Usuario            {                UserName = correo,                Email = correo,                EmailConfirmed = true,            };            var resultado = await userManager.CreateAsync(usuario, ContrasenaDemo);            if (!resultado.Succeeded)            {                throw new InvalidOperationException($"No se pudo crear el usuario demo '{correo}': {string.Join("; ", resultado.Errors.Select(e => e.Description))}");            }        }        if (!await userManager.IsInRoleAsync(usuario, rol))        {            await userManager.AddToRoleAsync(usuario, rol);        }        return usuario.Id;    }    private static async Task AsegurarProgramaProfesorAsync(        TesisDbContext contexto,        int idProfesor,        NivelPosgrado nivel,        string programa)    {        var existe = await contexto.ProfesoresPosgrado.AnyAsync(pp =>            pp.IdProfesor == idProfesor && pp.Nivel == nivel && pp.Programa == programa);        if (!existe)        {            contexto.ProfesoresPosgrado.Add(new ProfesorPosgrado            {                IdProfesor = idProfesor,                Nivel = nivel,                Programa = programa,            });        }    }}